[[[
  const u = hass?.config?.unit_system?.temperature || '°';
  const ts = states[variables.temp_sensor];
  const tsOk = !!ts && ts.state !== '' && ts.state != null && isFinite(Number(ts.state));
  /* the room's own thermometer is the number, when it has one */
  if (tsOk) return `${Math.round(Number(ts.state))}${u}`;
  const st = states[variables.climate_entity];
  if (!st) return '';
