card.name:
[[[
  const h = states[variables.pool_heater];
  const t = h?.attributes?.current_temperature;
  const u = hass?.config?.unit_system?.temperature || '°';
  return t != null ? `${Math.round(t)}${u}` : '';
]]]

card.background:
[[[
  const c = variables.chips.pool || {};
  if (!(states[variables.pool_switch]?.state === 'on')) return variables.chips.off.bg;
  const h = states[variables.pool_heater];
  const a = h?.attributes || {};
  const cur = a.current_temperature, set = a.temperature;
  let mood = 'resting';
  /* A climate-domain heater says outright whether it is firing; a
     water_heater (which is what a Pentair publishes) does not, so
     that one is read from how far it still has to go. */
  if (variables.pool_heater && h && h.state !== 'off' && h.state !== 'unavailable') {
    if (a.hvac_action === 'heating') mood = 'heating';
    else if (a.hvac_action === 'idle' || a.hvac_action === 'off') mood = 'warm';
    else if (cur != null && set != null) mood = (cur + 0.5 < set) ? 'heating' : 'warm';
  }
  return (c[mood] || c).bg;
]]]

