custom_fields.alert:
[[[
  /* One badge per kind of thing that is open, each counting only its own.
     Previously the glyph came from the first open sensor and the number
     from every one of them, so a garage door plus an entry door read as
     two garage doors. */
  const groups = (window.charroAlertGroups ? window.charroAlertGroups(variables, states) : []);
  if (!groups.length) return '';
  return groups.map(([icon, n]) =>
    `<ha-icon icon="${icon}" style="width:24px;height:24px;--mdc-icon-size:24px;vertical-align:-6px;"></ha-icon>${n > 1 ? ' ' + n : ''}`
  ).join(' ');
]]]

